.price-reference-header{display:flex;align-items:center;gap:12px;padding:22px 18px 18px;border-bottom:1px solid #e3ece6;position:relative}.price-reference-icon{background:#edf7f1;color:#19795a;width:38px;height:38px;border-radius:9px;display:grid;place-items:center}.price-reference-header h2{font-size:17px;line-height:1.4;margin:0;font-weight:600}.price-reference-header p{font-size:12px;color:#6c8075;margin:4px 0 0}.price-reference-close{position:absolute;right:14px;top:12px;border:0;background:none;padding:4px;color:#2c493a;cursor:pointer}
