.price-reference-meta{display:flex;justify-content:space-between;gap:12px;color:#6b7e72;font-size:11px;margin-bottom:10px}.price-reference-table-wrap{overflow-x:auto}.price-reference-table{border-collapse:collapse;width:100%;table-layout:fixed;min-width:680px}.price-reference-table th{background:#f3f7f4;font-weight:400;text-align:left;font-size:12px;color:#293e32;padding:8px 15px;border-bottom:1px solid #dce8e0}.price-reference-table th:nth-child(1){width:23%}.price-reference-table th:nth-child(2){width:27%}.price-reference-table th:nth-child(3){width:25%}.price-reference-table td{padding:16px 15px;border-bottom:1px solid #e0ebe3;vertical-align:middle;line-height:1.6}.price-reference-table small{display:block;margin-top:5px;font-size:11px;color:#6b8075;font-weight:400}.price-reference-table small.inline{display:inline;margin-left:4px}.price-reference-table em{font-style:normal;background:#edf7f1;color:#19795a;padding:2px 6px;margin-left:8px;white-space:nowrap}.price-reference-r{color:#16724f;font-size:15px;font-weight:700}
.price-reference-footer{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:14px 17px;border-top:1px solid #e3ece6;background:#fff;color:#6b8075;font-size:11px}.price-reference-footer a{display:block;margin-top:4px;font-size:10px;color:#7d8f83;text-decoration:none}.price-reference-footer>button{border:0;background:#19795a;color:white;border-radius:6px;padding:8px 17px;font-size:14px;cursor:pointer;flex-shrink:0}.price-reference-warning{color:#8c681f;background:#fff9e9;padding:9px 12px;border-radius:5px;font-size:12px;margin:0 0 12px}.price-reference-empty{text-align:center;padding:45px 15px;color:#7b8d80;min-height:180px}.price-seat-tabs{display:flex;align-items:center;gap:7px;margin:-6px 0 14px;flex-wrap:wrap}.price-seat-tabs button{border:1px solid #dce8df;border-radius:4px;background:#fff;color:#6b8075;padding:5px 9px;font-size:12px;cursor:pointer}.price-seat-tabs button.active{color:#19795a;background:#edf7f1;border-color:#bcdfca}.price-seat-tabs span{font-size:11px;color:#718579;margin-left:8px}.spinning{animation:price-spin 1s linear infinite}@keyframes price-spin{to{transform:rotate(360deg)}}
